from datetime import date, timedelta

# Find the earliest Friday the 13th starting from 0001-01-01 (proleptic Gregorian)
d = date(1, 1, 13)  # start checking the 13th of each month
earliest = None
while d.year == 1:
    if d.weekday() == 4:  # Friday
        earliest = d
        break
    # jump to 13th of next month
    if d.month == 12:
        break
    d = d.replace(month=d.month + 1)

if not earliest:
    # check subsequent years
    for yr in range(2, 401):
        for mo in range(1, 13):
            d = date(yr, mo, 13)
            if d.weekday() == 4:
                earliest = d
                break
        if earliest:
            break

print(f"Earliest Friday the 13th: {earliest}  (weekday={earliest.strftime('%A')})")

# Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
count = 0
for yr in range(1, 401):
    for mo in range(1, 13):
        if date(yr, mo, 13).weekday() == 4:
            count += 1

print(f"Friday the 13ths in a 400-year cycle: {count}")
print(f"Average per year: {count/400:.4f}")

# Bonus: which day-of-week is the 13th most often?
from collections import Counter
c = Counter()
for yr in range(1, 401):
    for mo in range(1, 13):
        c[date(yr, mo, 13).strftime('%A')] += 1

print("\n13th falls on each weekday (400-year cycle):")
for day in ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']:
    print(f"  {day:9s}: {c[day]}")
EOF

